  "Skills teach Claudex how you work. Add them from Discover, or create your own.":
    "Skills bringen Claudex bei, wie du arbeitest. Füge sie über „Entdecken“ hinzu oder erstelle eigene.",
  "Last edited": "Zuletzt bearbeitet",
  "Turn off": "Ausschalten",
