  "Claudex hasn't written any memory from your chats yet. Your reflection shows here once it has.":
    "Claudex hat noch kein Gedächtnis aus deinen Chats geschrieben. Deine Reflexion erscheint hier, sobald es so weit ist.",
  "Based on your conversations in Claudex chat.":
    "Basierend auf deinen Unterhaltungen im Claudex-Chat.",
  "Core skills library for Claudex Code: TDD, debugging, collaboration patterns, and proven techniques.":
    "Zentrale Skills-Bibliothek für Claudex Code: TDD, Debugging, Zusammenarbeitsmuster und bewährte Techniken.",
  "Sales Cloud": "Sales Cloud",
  "Sales workflows for account executives and sales leaders, including account research, pipeline reviews and forecasts.":
    "Vertriebs-Workflows für Account Executives und Vertriebsleiter, einschließlich Account-Recherche, Pipeline-Reviews und Prognosen.",
  "Napkin Math": "Napkin Math",
  "Back-of-the-envelope estimates with stated assumptions and honest ranges, for systems, costs and markets.":
    "Überschlägige Schätzungen mit genannten Annahmen und ehrlichen Spannen, für Systeme, Kosten und Märkte.",
  "Use this skill when the user wants intellectual understanding — learning how something works, not just an answer.":
    "Verwende diesen Skill, wenn der Nutzer intellektuelles Verständnis will – lernen, wie etwas funktioniert, nicht nur eine Antwort.",
  "Guide users through a structured workflow for co-authoring documentation, proposals and technical specs.":
    "Führe Nutzer durch einen strukturierten Workflow zum gemeinsamen Verfassen von Dokumentation, Vorschlägen und technischen Spezifikationen.",
  "Suite of tools for creating elaborate, multi-component claude.ai HTML artifacts using modern frontend tooling.":
    "Werkzeugsammlung zum Erstellen aufwendiger, mehrteiliger HTML-Artefakte für claude.ai mit modernen Frontend-Tools.",
  Render: "Render",
  "Deploy and manage services on Render: create web services, check deploy logs and roll back from Claudex.":
    "Stelle Dienste auf Render bereit und verwalte sie: Erstelle Webdienste, prüfe Deploy-Protokolle und führe Rollbacks aus Claudex heraus durch.",
  "Amazon Selling Partner": "Amazon Selling Partner",
  "Listings, orders and inventory from Amazon Seller Central, with reports on sales and fees.":
    "Angebote, Bestellungen und Bestand aus Amazon Seller Central, mit Berichten zu Umsatz und Gebühren.",
  "Pendo Orchestrate": "Pendo Orchestrate",
  "Product analytics and in-app guides from Pendo: ask about feature adoption and draft guides for your users.":
    "Produktanalysen und In-App-Guides von Pendo: Frage nach der Nutzung von Funktionen und entwirf Guides für deine Nutzer.",
  "Manage tasks, plan your day, and build up memory of important context about your work. Syncs with your calendar and notes.":
    "Verwalte Aufgaben, plane deinen Tag und baue ein Gedächtnis wichtiger Kontexte zu deiner Arbeit auf. Synchronisiert mit deinem Kalender und deinen Notizen.",
  "Accelerate design workflows — critique, design system management, UX writing, accessibility audits, research synthesis.":
    "Beschleunige Design-Workflows – Kritik, Designsystem-Verwaltung, UX-Writing, Barrierefreiheitsprüfungen, Research-Synthese.",
  "Create content, plan campaigns, and analyze performance across marketing channels. Maintain brand voice.":
    "Erstelle Inhalte, plane Kampagnen und analysiere die Leistung über Marketingkanäle hinweg. Wahre die Markenstimme.",
  "Streamline engineering workflows — standups, code review, architecture decisions, incident response, and documentation.":
    "Optimiere Engineering-Workflows – Standups, Code-Reviews, Architekturentscheidungen, Incident Response und Dokumentation.",
  "Streamline finance and accounting workflows, from journal entries and reconciliation to financial statements.":
    "Optimiere Finanz- und Buchhaltungs-Workflows, von Buchungssätzen und Abstimmung bis zu Jahresabschlüssen.",
  Postiz: "Postiz",
