  "No reply yet. Claudex may still be working on this response.":
    "Noch keine Antwort. Claudex arbeitet möglicherweise noch an dieser Antwort.",
  "Connection lost. Claudex may still be working on this response.":
    "Verbindung unterbrochen. Claudex arbeitet möglicherweise noch an dieser Antwort.",
  "Claudex will use your mouse and keyboard in {apps}.":
    "Claudex verwendet deine Maus und Tastatur in {apps}.",
  "the apps you allowed": "den von dir erlaubten Apps",
  "Other apps will be hidden until it finishes.":
    "Andere Apps werden bis zum Abschluss ausgeblendet.",
  "Press Esc to stop at any time.": "Drücke jederzeit Esc, um zu stoppen.",
  "Let Claudex see and act in the apps you allow, working in the background or with full control of your screen. Screenshots of those apps are sent to the model.":
    "Erlaube Claudex, die von dir freigegebenen Apps zu sehen und zu bedienen, im Hintergrund oder mit vollständiger Kontrolle über deinen Bildschirm. Screenshots dieser Apps werden an das Modell gesendet.",
  "Background: Claudex works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claudex takes control of your screen, mouse, and keyboard by default whenever Claudex uses an app you allow, without asking again.":
    "Hintergrund: Claudex arbeitet in den von dir erlaubten Apps, während du deinen Computer weiter verwendest, und fragt vor der vollständigen Übernahme deines Bildschirms nach deiner Erlaubnis. Vollständige Kontrolle: Sobald Claudex eine erlaubte App verwendet, übernimmt es standardmäßig die Kontrolle über Bildschirm, Maus und Tastatur, ohne erneut zu fragen.",
  "Claudex uses your computer's OpenSSH. Passwords are never saved; use an SSH key and ssh-agent to connect without prompts.":
    "Claudex verwendet OpenSSH auf deinem Computer. Passwörter werden niemals gespeichert. Verwende einen SSH-Schlüssel und ssh-agent, um dich ohne Rückfragen zu verbinden.",
  "Run Code sessions on another computer over SSH. Claudex uses this computer's OpenSSH and your SSH keys; passwords are never saved.":
    "Führe Code-Sitzungen über SSH auf einem anderen Computer aus. Claudex verwendet OpenSSH auf diesem Computer und deine SSH-Schlüssel. Passwörter werden niemals gespeichert.",
  ".md file must contain skill name and description formatted in YAML":
    "Eine .md-Datei muss den Namen und die Beschreibung des Skills im YAML-Format enthalten",
  ".zip or .skill file must include a SKILL.md file":
    "Eine .zip- oder .skill-Datei muss eine SKILL.md-Datei enthalten",
  "Claudex references the same knowledge every time you talk to it in this project.":
    "Claudex greift bei jedem Gespräch in diesem Projekt auf dasselbe Wissen zurück.",
  "Provide Claudex with relevant instructions and information for chats within {name}. This will work alongside your personal instructions and the selected style in a chat.":
    "Gib Claudex relevante Anweisungen und Informationen für Chats in {name}. Diese ergänzen deine persönlichen Anweisungen und den im Chat gewählten Stil.",
  "{n} installs": "{n} Installationen",
  "Shared {date}": "Geteilt am {date}",
  "{n} view": "{n} Aufruf",
  "{n} views": "{n} Aufrufe",
