  "{count} selected": "{count} ausgewählt",
  "Showing only {kind} that match “{query}”.":
    "Es werden nur {kind} angezeigt, die mit „{query}“ übereinstimmen.",
  "This deletes {email} from this computer together with its conversations, projects, artifacts and settings. It can't be undone.":
    "Dadurch werden {email} sowie die zugehörigen Gespräche, Projekte, Artefakte und Einstellungen von diesem Computer gelöscht. Dies kann nicht rückgängig gemacht werden.",
  "Scan with {method} to pay {amount}":
    "Mit {method} scannen, um {amount} zu bezahlen",
  "Pay {amount} there. Your plan and balance update when the payment goes through.":
    "Bezahle dort {amount}. Dein Tarif und dein Guthaben werden nach erfolgreicher Zahlung aktualisiert.",
  "The payment page for {amount} opened in your browser. This window updates when the payment goes through.":
    "Die Zahlungsseite für {amount} wurde in deinem Browser geöffnet. Dieses Fenster wird nach erfolgreicher Zahlung aktualisiert.",
  "Amount ({currency})": "Betrag ({currency})",
  "Fee ({percent}%)": "Gebühr ({percent}%)",
  "QR code to pay {amount} with {method}":
    "QR-Code zur Zahlung von {amount} mit {method}",
  "{count} hook that runs commands": "{count} Hook, der Befehle ausführt",
  "{count} hooks that run commands": "{count} Hooks, die Befehle ausführen",
  "Added. It also uses {services}, which need signing in before Claudex can use them.":
    "Hinzugefügt. Verwendet außerdem {services}; dort musst du dich anmelden, bevor Claudex sie nutzen kann.",
  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Anthropic, and Anthropic cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Vergewissere dich, dass du einem Plugin vertraust, bevor du es installierst, aktualisierst oder verwendest. Plugins aus Marktplätzen werden nicht von Anthropic kontrolliert. Anthropic kann weder prüfen, ob sie wie vorgesehen funktionieren, noch garantieren, dass sie unverändert bleiben. Weitere Informationen findest du auf der jeweiligen Plugin-Homepage.",
  "Updated tasks · {done} of {total} done":
    "Aufgaben aktualisiert · {done} von {total} erledigt",
  "Bypass all permission checks and let Claudex work uninterrupted in folders you confirm. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Umgehe alle Berechtigungsprüfungen und lass Claudex in von dir bestätigten Ordnern ohne Unterbrechung arbeiten. Das eignet sich für Aufgaben wie das Beheben von Lint-Fehlern oder das Erstellen von Standardcode. Claudex beliebige Befehle ausführen zu lassen ist riskant und kann zu Datenverlust, Systemschäden oder dem Abfluss von Daten führen, etwa durch Prompt-Injection-Angriffe.",
  "How Claudex structures its responses in Code sessions. Applies to new sessions; the session menu can override it for a single session.":
    "Wie Claudex seine Antworten in Code-Sitzungen strukturiert. Gilt für neue Sitzungen; im Sitzungsmenü kannst du dies für eine einzelne Sitzung überschreiben.",
