  "Select Xcode": "Xcode auswählen",
  "Xcode is installed, but your Mac’s command-line tools don’t point at it. In Xcode, open Settings → Locations and pick your Xcode under Command Line Tools.":
    "Xcode ist installiert, aber die Kommandozeilen-Tools deines Mac verweisen nicht darauf. Öffne in Xcode Einstellungen → Locations und wähle dein Xcode unter Command Line Tools aus.",
  "Xcode is installed, but your Mac’s command-line tools don’t point at it. Paste this in Terminal, then press Enter and type your Mac password when it asks:":
    "Xcode ist installiert, aber die Kommandozeilen-Tools deines Macs sind nicht darauf ausgerichtet. Füge dies im Terminal ein, drücke dann die Eingabetaste und gib dein Mac-Passwort ein, wenn du dazu aufgefordert wirst:",
  "Simulator installed": "Simulator installiert",
  "Install Simulator": "Simulator installieren",
  "When Xcode first opens, keep iOS selected and click Download & Install.":
    "Wenn Xcode zum ersten Mal geöffnet wird, lass iOS ausgewählt und klicke auf „Download & Install“.",
  "Available once Xcode is installed.":
    "Verfügbar, sobald Xcode installiert ist.",
  "Available once Xcode is selected.":
    "Verfügbar, sobald Xcode ausgewählt wurde.",
  "Checking for the simulator runtime…": "Simulator-Laufzeit wird geprüft…",
