  "Open Xcode": "Xcode öffnen",
  "Open Mac App Store": "Mac App Store öffnen",
  "Xcode is a trademark of Apple Inc., registered in the U.S. and other countries.":
    "Xcode ist eine Marke von Apple Inc., eingetragen in den USA und anderen Ländern.",
