  "Free from developer.android.com. Bundles the SDK and emulator.":
    "Kostenlos von developer.android.com. Enthält das SDK und den Emulator.",
  "Finish the setup wizard": "Einrichtungsassistenten abschließen",
  "Open Android Studio and complete its setup wizard to install the SDK.":
    "Öffne Android Studio und schließe den Einrichtungsassistenten ab, um das SDK zu installieren.",
  "System image installed": "System-Image installiert",
  "Install a system image": "System-Image installieren",
  "In Android Studio: Tools, then SDK Manager, then SDK Platforms.":
    "In Android Studio: Tools, dann SDK Manager, dann SDK Platforms.",
  "Available once the SDK is installed.":
    "Verfügbar, sobald das SDK installiert ist.",
  "Virtual device created": "Virtuelles Gerät erstellt",
