  "Career chat": "Karriereberatung",
  "Prepare for an interview": "Auf ein Vorstellungsgespräch vorbereiten",
  "Help me prepare for a job interview. I'll share the role and my background, then you ask me likely questions one at a time and give feedback on each answer.":
    "Hilf mir, mich auf ein Vorstellungsgespräch vorzubereiten. Ich nenne dir die Stelle und meinen Werdegang, dann stellst du mir nacheinander typische Fragen und gibst mir zu jeder Antwort Feedback.",
  "Sharpen my resume": "Meinen Lebenslauf schärfen",
  "Read my resume, point out what's unclear or missing, then rewrite the weakest parts so my results stand out. Here it is:\n\n":
    "Lies meinen Lebenslauf, zeig mir, was unklar ist oder fehlt, und formuliere die schwächsten Stellen so um, dass meine Erfolge hervorstechen. Hier ist er:\n\n",
  "Rehearse a hard conversation": "Ein schwieriges Gespräch üben",
  "Role-play a conversation I need to have at work. I'll tell you who it's with and what I want to say; you play them realistically, then tell me what worked.":
    "Spiel mit mir ein Gespräch durch, das ich bei der Arbeit führen muss. Ich sage dir, mit wem und was ich sagen will; du spielst die andere Person realistisch und sagst mir danach, was funktioniert hat.",
  "Map my next career step": "Meinen nächsten Karriereschritt planen",
  "Help me plan my next career step. Ask me what I do now, what I enjoy and where I'd like to be, then suggest a few paths and what each would take.":
    "Hilf mir, meinen nächsten Karriereschritt zu planen. Frag mich, was ich jetzt mache, was mir Freude macht und wo ich hinwill, und schlag dann ein paar Wege vor und was jeder erfordern würde.",
  "Handle a tricky work situation":
    "Eine heikle Situation bei der Arbeit meistern",
  "Help me handle a tricky situation at work: lay out my options and help me pick a next step. Here's what's going on: ":
    "Hilf mir mit einer heiklen Situation bei der Arbeit: Zeig mir meine Optionen und hilf mir, den nächsten Schritt zu wählen. Darum geht es: ",
