  "Already set to merge when ready.":
    "Bereits auf „Zusammenführen, wenn bereit“ gesetzt.",
  "GitHub is blocking this merge. See what the pull request needs.":
    "GitHub blockiert diesen Merge. Sieh nach, was der Pull Request braucht.",
