    "Dieser Branch liegt hinter seinem Basis-Branch. Aktualisiere ihn vor dem Merge.",
  "The pull request changed. See what changed before you merge.":
    "Der Pull Request hat sich geändert. Sieh dir die Änderungen vor dem Merge an.",
  "Auto-merge isn’t available in SSH sessions yet. Use gh or GitHub directly.":
    "Auto-Merge ist in SSH-Sitzungen noch nicht verfügbar. Nutze gh oder GitHub direkt.",
  "Draft PRs can’t use auto-merge.":
    "Entwurfs-PRs können Auto-Merge nicht nutzen.",
  "PR is ready to merge now — nothing to wait for.":
    "Der PR kann jetzt zusammengeführt werden – es gibt nichts zu warten.",
  "This repository doesn’t allow auto-merge. An admin can turn on Allow auto-merge in the repository settings on GitHub.":
    "Dieses Repository erlaubt kein Auto-Merge. Ein Admin kann „Allow auto-merge“ in den Repository-Einstellungen auf GitHub aktivieren.",
  "This pull request is ready to merge now, so there’s nothing for auto-merge to wait for.":
    "Dieser Pull Request kann jetzt zusammengeführt werden, Auto-Merge muss also auf nichts warten.",
  "This repository doesn’t allow squash merging, which auto-merge uses here. Turn on auto-merge on GitHub to pick an allowed merge method.":
    "Dieses Repository erlaubt kein Squash-Merging, das Auto-Merge hier nutzt. Aktiviere Auto-Merge auf GitHub, um eine erlaubte Merge-Methode zu wählen.",
  "GitHub only offers auto-merge on protected base branches, and this one isn’t protected. An admin can add a branch protection rule on GitHub.":
    "GitHub bietet Auto-Merge nur für geschützte Basis-Branches an, und dieser ist nicht geschützt. Ein Admin kann auf GitHub eine Branch-Schutzregel hinzufügen.",
  "GitHub doesn’t support auto-merge on stacked pull requests.":
    "GitHub unterstützt kein Auto-Merge für gestapelte Pull Requests.",
  "Your GitHub account doesn’t have permission to change auto-merge on this repository. Ask a repository admin for access.":
    "Dein GitHub-Konto darf Auto-Merge in diesem Repository nicht ändern. Bitte einen Repository-Admin um Zugriff.",
  "This pull request changes a workflow file, and your GitHub CLI sign-in lacks the workflow scope. Run gh auth refresh -s workflow to add it.":
    "Dieser Pull Request ändert eine Workflow-Datei, und deiner GitHub-CLI-Anmeldung fehlt der workflow-Scope. Führe gh auth refresh -s workflow aus, um ihn hinzuzufügen.",
