  "Dismiss the uncommitted work": "Nicht committete Arbeit ausblenden",
  "Continue the work in progress on {branch}: look at the uncommitted changes, tell me what state they’re in, and finish what’s started.":
    "Setze die laufende Arbeit auf {branch} fort: Sieh dir die nicht committeten Änderungen an, sag mir, in welchem Zustand sie sind, und bring zu Ende, was begonnen wurde.",
  "Next steps": "Nächste Schritte",
