  "and 1 more": "und 1 weitere",
  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.":
    "Desktop-Sitzungen automatisch archivieren, wenn der zugehörige Pull Request gemergt oder geschlossen wird. Nach dem Merge entfernt das Archivieren auch den Worktree der Sitzung und löscht ihren Branch. Nicht gepushte Arbeit bleibt erhalten.",
  "Archive this session when its pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept. This session only; other sessions follow the default in Settings → Claudex Code.":
    "Diese Sitzung archivieren, wenn ihr Pull Request gemergt oder geschlossen wird. Nach dem Merge entfernt das Archivieren auch den Worktree der Sitzung und löscht ihren Branch. Nicht gepushte Arbeit bleibt erhalten. Nur diese Sitzung; andere Sitzungen folgen der Standardeinstellung unter Einstellungen → Claudex Code.",
  "Git won’t check out a branch in two folders at once. Run git worktree list in the repository to see which folder has this branch, switch that folder to a different branch, then try again.":
    "Git checkt einen Branch nicht in zwei Ordnern gleichzeitig aus. Führe im Repository git worktree list aus, um zu sehen, welcher Ordner diesen Branch hat, wechsle dort zu einem anderen Branch und versuche es dann erneut.",
