  "Already installed and open in its own window.":
    "Bereits installiert und in einem eigenen Fenster geöffnet.",
  "This browser isn’t offering to install this artifact here. If you’ve installed it, open it from your desktop or app launcher. If this is a private window, open the page in a regular window.":
    "Dieser Browser bietet hier keine Installation dieses Artefakts an. Falls du es bereits installiert hast, öffne es über deinen Desktop oder den App-Launcher. Wenn dies ein privates Fenster ist, öffne die Seite in einem normalen Fenster.",
  "You closed the install dialog. Reload the page to try again.":
    "Du hast das Installationsfenster geschlossen. Lade die Seite neu, um es noch einmal zu versuchen.",
  "This browser couldn’t draw the artifact’s icon, and installing needs one. If a privacy setting or extension blocks it, turn that off, or try another browser.":
    "Dieser Browser konnte das Symbol des Artefakts nicht darstellen, das für die Installation erforderlich ist. Wenn eine Datenschutzeinstellung oder Erweiterung das Symbol blockiert, deaktiviere diese oder versuche es mit einem anderen Browser.",
  "Adding to the Dock needs Safari 17 or later on macOS Sonoma or later.":
    "Zum Hinzufügen zum Dock ist Safari 17 oder neuer unter macOS Sonoma oder neuer erforderlich.",
  "This browser doesn’t offer to install artifacts. Try Chrome or Edge.":
    "Dieser Browser bietet keine Installation von Artefakten an. Probiere es mit Chrome oder Edge.",
  "Tap Share in Safari’s toolbar. If you don’t see it, tap the More button (three dots) first.":
    "Tippe in der Symbolleiste von Safari auf „Teilen“. Wenn du die Option nicht siehst, tippe zuerst auf die Schaltfläche „Mehr“ (drei Punkte).",
  "Tap Share in Chrome’s address bar.":
    "Tippe in der Adressleiste von Chrome auf „Teilen“.",
  "Open your browser’s menu and tap Share.":
    "Öffne das Menü deines Browsers und tippe auf „Teilen“.",
  "Tap Add to Home Screen. You may need to scroll to find it.":
    "Tippe auf „Zum Home-Bildschirm“. Eventuell musst du scrollen, um die Option zu finden.",
  "Tap Add.": "Tippe auf „Hinzufügen“.",
  "If you don’t see Add to Home Screen, open this page in Safari and try again.":
    "Wenn du „Zum Home-Bildschirm“ nicht siehst, öffne diese Seite in Safari und versuch es noch einmal.",
  "Open it from your Home Screen. You may need to sign in again the first time.":
    "Öffne das Artefakt über deinen Home-Bildschirm. Beim ersten Mal musst du dich möglicherweise erneut anmelden.",
  "Tap Chrome’s More button (three dots).":
    "Tippe in Chrome auf die Schaltfläche „Mehr“ (drei Punkte).",
  "Open your browser’s menu.": "Öffne das Menü deines Browsers.",
  "Tap Add to Home screen, then follow the prompts.":
    "Tippe auf „Zum Startbildschirm hinzufügen“ und folge dann den Anweisungen.",
  "In Safari’s menu bar, choose File, then Add to Dock. This needs macOS Sonoma or later.":
    "Wähle in der Menüleiste von Safari „Ablage“ und dann „Zum Dock hinzufügen“. Dafür ist macOS Sonoma oder neuer erforderlich.",
  "Click Add.": "Klicke auf „Hinzufügen“.",
  "Open it from your Dock. You may need to sign in again the first time.":
    "Öffne es über dein Dock. Beim ersten Mal musst du dich möglicherweise erneut anmelden.",
