  "This is an example project. Create a new project to work with your own documents.":
    "Dies ist ein Beispielprojekt. Erstelle ein neues Projekt, um mit deinen eigenen Dokumenten zu arbeiten.",
  "A project for studying your course materials, where Claudex helps visualize key concepts, build comprehensive study guides, and tutor you according to your learning needs.":
    "Ein Projekt zum Lernen deiner Kursmaterialien, in dem Claudex Schlüsselkonzepte visualisiert, umfassende Lernleitfäden erstellt und dich nach deinen Lernbedürfnissen unterstützt.",
  "A project for exploring career opportunities, where Claudex helps match your skills to potential careers, improve your resume, and develop personalized roadmaps for professional growth.":
    "Ein Projekt zur Erkundung von Karrierechancen, in dem Claudex deine Fähigkeiten passenden Berufen zuordnet, deinen Lebenslauf verbessert und individuelle Entwicklungspläne erstellt.",
  "A project for developing academic research, where Claudex helps identify key themes in your research, create structured outlines, and provide feedback to improve your drafts.":
    "Ein Projekt zur akademischen Forschung, in dem Claudex zentrale Themen erkennt, strukturierte Gliederungen erstellt und Feedback zur Verbesserung deiner Entwürfe gibt.",
