  "Linked to this computer.": "Mit diesem Computer verknüpft.",
  "Couldn’t link this task to this computer.":
    "Diese Aufgabe konnte nicht mit diesem Computer verknüpft werden.",
  "Computer access is off, so tasks that require a computer won’t run.":
    "Der Computerzugriff ist deaktiviert, daher werden Aufgaben, die einen Computer benötigen, nicht ausgeführt.",
  "This task will run on schedule once Computer access is on.":
    "Diese Aufgabe wird planmäßig ausgeführt, sobald der Computerzugriff aktiviert ist.",
  "Permission mode is set to Auto.":
    "Der Berechtigungsmodus ist auf Auto eingestellt.",
  "Skip all approvals is on.": "Alle Genehmigungen überspringen ist aktiviert.",
  "Claudex runs on its own and pauses if anything looks unsafe. This includes using your connectors and apps on your computer, unless you turn them off.":
    "Claudex arbeitet selbstständig und pausiert, wenn etwas unsicher erscheint. Dazu gehört die Nutzung deiner Konnektoren und Apps auf deinem Computer, sofern du sie nicht deaktivierst.",
  "Claudex never pauses, even for unsafe actions. This includes using your connectors and apps on your computer. You can turn off individual connectors in the + menu.":
    "Claudex pausiert nie, auch nicht bei unsicheren Aktionen. Dazu gehört die Nutzung deiner Konnektoren und Apps auf deinem Computer. Einzelne Konnektoren kannst du im Menü + deaktivieren.",
  "Claudex will work, browse the web, and use any connectors you’ve enabled without pausing for approval. This can put your data at risk.":
    "Claudex arbeitet, surft im Web und nutzt alle aktivierten Konnektoren, ohne zur Genehmigung zu pausieren. Dadurch können deine Daten gefährdet werden.",
  "See safe use tips": "Tipps zur sicheren Nutzung ansehen",
  "1 tool": "1 Tool",
  "{count} tools": "{count} Tools",
