  "Full control · {target}": "Vollzugriff · {target}",
  "Background · {target}": "Hintergrund · {target}",
  "Claudex is working on your computer. You’ll see updates here as Claudex makes progress.":
    "Claudex arbeitet auf deinem Computer. Hier siehst du Updates, während Claudex Fortschritte macht.",
  "Chats compact less since tools aren’t pre-loaded.":
    "Chats werden seltener komprimiert, da Tools nicht vorab geladen werden.",
  "Chats compact more often since tools are always there.":
    "Chats werden häufiger komprimiert, da Tools immer geladen sind.",
  "Tool access set to load when needed":
    "Toolzugriff auf „Bei Bedarf laden“ gesetzt",
  "Tool access set to load all tools up front":
    "Toolzugriff auf „Alle Tools vorab laden“ gesetzt",
  "This feature gives Claudex network access to create and analyze files, which has <a>security risks</a>. Monitor chats closely when using this feature.":
    "Diese Funktion gibt Claudex Netzwerkzugriff, um Dateien zu erstellen und zu analysieren, was <a>Sicherheitsrisiken</a> birgt. Beobachte Chats genau, wenn du diese Funktion nutzt.",
  "Give Claudex network access to install packages and libraries in order to perform advanced data analysis, custom visualizations, and specialized file processing. Monitor chats closely as this comes with <a>security risks</a>.":
    "Gib Claudex Netzwerkzugriff, um Pakete und Bibliotheken für erweiterte Datenanalysen, eigene Visualisierungen und spezielle Dateiverarbeitung zu installieren. Beobachte Chats genau, da dies <a>Sicherheitsrisiken</a> birgt.",
  "Dictation is unavailable": "Diktieren ist nicht verfügbar",
  "Dictate again": "Erneut diktieren",
  "Right-click for microphone settings":
    "Rechtsklick für Mikrofoneinstellungen",
  "Dictate a reply": "Antwort diktieren",
  "Write a reply": "Antwort schreiben",
  "Claudex can access all domains on the internet.":
    "Claudex kann auf alle Domains im Internet zugreifen.",
  "Claudex can only access domains you specify below. Add domains individually using wildcards if needed.":
    "Claudex kann nur auf die unten angegebenen Domains zugreifen. Füge Domains bei Bedarf einzeln mit Platzhaltern hinzu.",
  "Claudex can access common package managers plus any additional domains you specify below. <a>View package manager domains</a>.":
    "Claudex kann auf gängige Paketmanager sowie auf alle unten angegebenen zusätzlichen Domains zugreifen. <a>Paketmanager-Domains ansehen</a>.",
  "Enter a valid domain (e.g., example.com or *.example.com)":
    "Gib eine gültige Domain ein (z. B. example.com oder *.example.com)",
  "Remove {host}": "{host} entfernen",
  "Allow Claudex to generate memory from your chats and Cowork sessions.":
    "Erlaube Claudex, aus deinen Chats und Cowork-Sitzungen Erinnerungen zu erstellen.",
  "Or reply directly…": "Oder direkt antworten…",
  "End the voice session to continue":
    "Beende die Sprachsitzung, um fortzufahren",
  "End the voice session first": "Beende zuerst die Sprachsitzung",
  "File attachments were removed because the draft was reset after an unfinished voice conversation. Attach them again.":
    "Dateianhänge wurden entfernt, weil der Entwurf nach einer nicht abgeschlossenen Sprachunterhaltung zurückgesetzt wurde. Hänge sie erneut an.",
  "Deleting your account is permanent. You will have no way of recovering your account or conversation data.":
    "Das Löschen deines Kontos ist endgültig. Dein Konto und deine Gesprächsdaten können nicht wiederhergestellt werden.",
  "Are you sure you want to delete your account?":
    "Möchtest du dein Konto wirklich löschen?",
  "I understand": "Ich verstehe",
  "Account deleted": "Konto gelöscht",
  "Built-in browser": "Integrierter Browser",
  "An error occurred while deleting your account. Please try again or contact support.":
    "Beim Löschen deines Kontos ist ein Fehler aufgetreten. Versuche es erneut oder kontaktiere den Support.",
  "Not signed in.": "Nicht angemeldet.",
  "For this task, Claudex never pauses, even for unsafe actions.":
    "Bei dieser Aufgabe pausiert Claudex nie, auch nicht bei unsicheren Aktionen.",
  "Run at exact time": "Zur genauen Uhrzeit ausführen",
  "By default, scheduled tasks use a randomized delay of several minutes for server performance.":
    "Standardmäßig werden geplante Aufgaben zur Verbesserung der Serverleistung um einige Minuten zufällig verzögert.",
  "Notify me when this task finishes":
    "Benachrichtige mich, wenn diese Aufgabe abgeschlossen ist",
  "Claudex will send you a one-line summary when each run completes — only when there’s something worth telling you for tasks that watch for a condition.":
    "Claudex sendet dir nach jedem Durchlauf eine einzeilige Zusammenfassung – bei Aufgaben, die eine Bedingung überwachen, nur wenn es etwas Berichtenswertes gibt.",
  "Push notification": "Push-Benachrichtigung",
  "Invalid scheduled task.": "Ungültige geplante Aufgabe.",
  "Only runs while your computer is on. Use this if the task needs access to local files or desktop extensions.":
    "Wird nur ausgeführt, wenn dein Computer eingeschaltet ist. Verwende diese Option, wenn die Aufgabe Zugriff auf lokale Dateien oder Desktop-Erweiterungen benötigt.",
  Slack: "Slack",
  "Block nonessential services": "Nicht notwendige Dienste blockieren",
  "Connector favicons, artifact-preview and MCP Apps iframes, and the Linux spellcheck dictionary. Connector widgets fall back to text; spellcheck is off on Linux.":
    "Favicons von Konnektoren, Artifact-Vorschau und MCP-Apps-iFrames sowie das Linux-Rechtschreibwörterbuch. Konnektor-Widgets fallen auf Text zurück; die Rechtschreibprüfung ist unter Linux deaktiviert.",
  "This disables connector icons, hosted artifact previews and MCP Apps widgets, and also turns spellcheck off on Linux. Artifacts still render locally. Connectors that return MCP Apps show the text tool result instead of the widget.":
    "Dadurch werden Connector-Symbole, gehostete Artefaktvorschauen und MCP Apps-Widgets deaktiviert. Unter Linux wird außerdem die Rechtschreibprüfung ausgeschaltet. Artefakte werden weiterhin lokal gerendert. Connectoren, die MCP Apps zurückgeben, zeigen das Textergebnis des Tools statt des Widgets an.",
  "Allow Claudex to use coarse location metadata (city/region) to improve product experiences. <a>Learn more</a>.":
    "Erlaube Claudex, grobe Standortmetadaten (Stadt/Region) zur Verbesserung der Produkterfahrung zu nutzen. <a>Mehr erfahren</a>.",
