  "This folder contains a protected location on your device and can’t be shared with this session. Try a more specific folder instead.":
    "Dieser Ordner enthält einen geschützten Speicherort auf deinem Gerät und kann nicht mit dieser Sitzung geteilt werden. Versuche es mit einem spezifischeren Ordner.",
  "This folder is a protected location on your device and can’t be shared with this session.":
    "Dieser Ordner ist ein geschützter Speicherort auf deinem Gerät und kann nicht mit dieser Sitzung geteilt werden.",
  "This folder contains Claudex’s app data and can’t be shared with this session. Try a more specific folder instead.":
    "Dieser Ordner enthält App-Daten von Claudex und kann nicht mit dieser Sitzung geteilt werden. Versuche es mit einem spezifischeren Ordner.",
  "Some folders couldn’t be added.":
    "Einige Ordner konnten nicht hinzugefügt werden.",
  "Bypass all permission checks and let Claudex work uninterrupted. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Alle Berechtigungsprüfungen umgehen und Claudex ohne Unterbrechungen arbeiten lassen. Dies eignet sich für Workflows wie das Beheben von Lint-Fehlern oder das Generieren von Standardcode. Claudex beliebige Befehle ausführen zu lassen, ist riskant und kann zu Datenverlust, Systembeschädigung oder Datenabfluss führen (z. B. durch Prompt-Injection-Angriffe).",
  "See best practices for safe usage":
    "Best Practices für die sichere Nutzung ansehen",
  "Switched to {toName}": "Zu {toName} gewechselt",
