  "This extension was uploaded by your organization.":
    "Diese Erweiterung wurde von deiner Organisation hochgeladen.",
  "Community connectors have undergone automated reviews but aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only connect developers you trust.":
    "Community-Konnektoren wurden automatisiert geprüft, sind aber nicht von Anthropic verifiziert. Wir kontrollieren ihre Tools nicht und können weder die vorgesehene Funktion noch deren Unveränderlichkeit garantieren. Verbinde daher nur Konnektoren von Entwicklern, denen du vertraust.",
  "Community desktop extensions aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only install desktop extensions from developers you trust.":
    "Community-Desktop-Erweiterungen sind nicht von Anthropic verifiziert. Wir kontrollieren ihre Tools nicht und können weder die vorgesehene Funktion noch deren Unveränderlichkeit garantieren. Installiere daher nur Desktop-Erweiterungen von Entwicklern, denen du vertraust.",
  "Community plugins aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only add plugins from developers you trust.":
    "Community-Plugins sind nicht von Anthropic verifiziert. Wir kontrollieren ihre Tools nicht und können weder die vorgesehene Funktion noch deren Unveränderlichkeit garantieren. Füge daher nur Plugins von Entwicklern hinzu, denen du vertraust.",
  "Connectors let Claudex work with your team’s tools and data. Add them from the directory, or add a custom one.":
    "Mit Konnektoren kann Claudex die Tools und Daten deines Teams nutzen. Füge sie aus dem Verzeichnis hinzu oder erstelle einen benutzerdefinierten Konnektor.",
  "Connectors let Claudex work with your team’s tools and data. Add them from the directory.":
    "Mit Konnektoren kann Claudex die Tools und Daten deines Teams nutzen. Füge sie aus dem Verzeichnis hinzu.",
  "Kept on the server, sent only to this connector and never shown again. Servers that sign in with OAuth don’t need one: use Connect after adding.":
    "Wird auf dem Server gespeichert, nur an diesen Konnektor gesendet und nie wieder angezeigt. Server mit OAuth-Anmeldung benötigen kein Token: Nutze nach dem Hinzufügen „Verbinden“.",
  "Incorrect code entered. Check that the code matches what you received in your other browser or device and try again.":
    "Falscher Code eingegeben. Prüfe, ob der Code mit dem übereinstimmt, den du in deinem anderen Browser oder auf deinem anderen Gerät erhalten hast, und versuche es erneut.",
