    "Entspricht nicht den erlaubten Zeichen",
  "Lookarounds and backreferences aren't supported — rewrite without (?=, (?!, (?<=, (?<! or \\1-style references":
    "Lookarounds und Rückverweise werden nicht unterstützt — schreibe den Ausdruck ohne (?=, (?!, (?<=, (?<! oder Verweise im Stil von \\1 neu",
  "Mark the part each customer fills in, like ${user_config.mydomain}":
    "Markiere den vom Kunden auszufüllenden Teil, etwa ${user_config.mydomain}",
  "Must be 400 characters or fewer": "Darf höchstens 400 Zeichen lang sein",
  "Not a valid regular expression": "Kein gültiger regulärer Ausdruck",
  "Only the subdomain may vary — end the host with your literal domain, e.g. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$":
    "Nur die Subdomain darf variieren — beende den Host mit deiner festen Domain, z. B. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$",
  "Pattern must end with $ so it can't match a longer host":
    "Das Muster muss mit $ enden, damit es keinem längeren Host entspricht",
  "Pattern must start with ^https://": "Das Muster muss mit ^https:// beginnen",
  "Remove the @ — userinfo before the host isn't allowed":
    "Entferne das @ — Benutzerinformationen vor dem Host sind nicht erlaubt",
  "Server URL must start with https://":
    "Die Server-URL muss mit https:// beginnen",
  "The subdomain slot can't use wildcards that match `/`, `.`, `?`, `#` or `@` — use a character class like [a-z0-9-]+ instead of .+ or \\S+":
    "Der Subdomain-Platzhalter darf keine Wildcards verwenden, die `/`, `.`, `?`, `#` oder `@` treffen — verwende eine Zeichenklasse wie [a-z0-9-]+ statt .+ oder \\S+",
  "This field is required": "Dieses Feld ist erforderlich",
  "Use one ${user_config.key} only": "Verwende nur ein ${user_config.key}",
  "Edit connector": "Connector bearbeiten",
  "Delete and re-add connectors to edit custom OAuth Client IDs.":
    "Löschen Sie den Connector und fügen Sie ihn erneut hinzu, um benutzerdefinierte OAuth-Client-IDs zu bearbeiten.",
  "Delete and re-add connectors to edit custom OAuth Client Secrets.":
    "Löschen Sie den Connector und fügen Sie ihn erneut hinzu, um benutzerdefinierte OAuth-Clientgeheimnisse zu bearbeiten.",
  "Claudex can’t reach a local address like this one. Enter a public https:// URL.":
    "Claudex kann eine lokale Adresse wie diese nicht erreichen. Geben Sie eine öffentliche https://-URL ein.",
  "Turn on computer use?": "Computer-Nutzung aktivieren?",
  "Grant macOS permissions": "macOS-Berechtigungen erteilen",
  "Keep in mind:": "Bitte beachten:",
  "Some actions can’t be undone.":
    "Manche Aktionen lassen sich nicht rückgängig machen.",
  "Apps you approve could open other apps that you haven’t approved.":
    "Freigegebene Apps könnten andere, nicht freigegebene Apps öffnen.",
  "Websites and docs could contain malicious instructions that misdirect Claudex.":
    "Websites und Dokumente könnten schädliche Anweisungen enthalten, die Claudex fehlleiten.",
  "Close anything sensitive. Claudex can see your screen.":
    "Schließe alles Vertrauliche. Claudex kann deinen Bildschirm sehen.",
  "Close anything sensitive. Claudex can see what’s on screen in the apps you approve, and your whole screen when Claudex has full control.":
    "Schließe alles Vertrauliche. Claudex sieht, was in freigegebenen Apps auf dem Bildschirm ist, und bei voller Kontrolle den ganzen Bildschirm.",
  "This is a research preview. Start with tasks where mistakes are easy to fix.":
    "Dies ist eine Forschungsvorschau. Beginne mit Aufgaben, bei denen sich Fehler leicht beheben lassen.",
  "Read safe use tips": "Tipps zur sicheren Nutzung lesen",
  "Computer use is on. To finish setup, grant the macOS permissions below.":
    "Die Computer-Nutzung ist aktiv. Erteile die macOS-Berechtigungen unten, um die Einrichtung abzuschließen.",
  Denied: "Verweigert",
  "Not requested": "Nicht angefragt",
  "Background computer use": "Computer-Nutzung im Hintergrund",
  "Claudex will see your whole screen and use your mouse and keyboard on it. You’ll approve the apps Claudex asks for, but on this system access can’t be limited to them, and you won’t confirm each step Claudex performs.":
    "Claudex sieht deinen ganzen Bildschirm und nutzt Maus und Tastatur darauf. Du gibst die angefragten Apps frei, aber auf diesem System lässt sich der Zugriff nicht darauf beschränken, und du bestätigst nicht jeden Schritt.",
  "Claudex will see the apps you approve and click and type in them, working in the background while you keep using your computer or taking full control of your screen. Which of those Claudex does by default is set under Settings → This computer → Computer use. You’ll approve each app, but not confirm each step Claudex performs.":
    "Claudex sieht freigegebene Apps und klickt und tippt darin – im Hintergrund, während du weiterarbeitest, oder mit voller Kontrolle über den Bildschirm. Was standardmäßig gilt, legst du unter Einstellungen → Dieser Computer → Computer-Nutzung fest. Du gibst jede App frei, bestätigst aber nicht jeden Schritt.",
  "Claudex can now control your applications in the background without taking over your screen, and will ask your permission if Claudex needs full control of your mouse and keyboard. If you’d prefer Claudex to default to full control instead of background mode, you can change this at any time under Settings → This computer → Computer use.":
    "Claudex kann deine Apps jetzt im Hintergrund steuern, ohne den Bildschirm zu übernehmen, und fragt nach, wenn es die volle Kontrolle über Maus und Tastatur braucht. Wenn Claudex standardmäßig die volle Kontrolle nutzen soll, kannst du das jederzeit unter Einstellungen → Dieser Computer → Computer-Nutzung ändern.",
  "for Mac": "für Mac",
  "Quit {appName}": "{appName} beenden",
  "Copy version {version} to clipboard":
    "Version {version} in die Zwischenablage kopieren",
  "Copied version to clipboard": "Version in die Zwischenablage kopiert",
