  "Claudex will browse and interact with any website without asking. Applies to new sessions. This setting can put your data at risk.":
    "Claudex wird ohne Nachfrage jede Website aufrufen und mit ihr interagieren. Gilt für neue Sitzungen. Diese Einstellung kann deine Daten gefährden.",
  "Claudex will take actions without asking for your permission, including on websites you haven’t approved.":
    "Claudex wird ohne deine Erlaubnis Aktionen ausführen, auch auf Websites, die du nicht genehmigt hast.",
