  "To continue, click the link sent to":
    "Klicke zum Fortfahren auf den Link, der an diese Adresse gesendet wurde",
  "Resend email": "E-Mail erneut senden",
  "Use verification code to continue": "Mit Bestätigungscode fortfahren",
