    "Gib diesen Bestätigungscode dort ein, wo du zuerst versucht hast, dich anzumelden",
  "Sign in here instead": "Stattdessen hier anmelden",
  "SSH sessions": "SSH-Sitzungen",
  "Allowed connector tools": "Erlaubte Konnektor-Tools",
  "Connector tools Claudex can use on an SSH host without a permission prompt.":
    "Konnektor-Tools, die Claudex auf einem SSH-Host ohne Berechtigungsabfrage verwenden kann.",
  "Claudex can use each tool on the SSH host shown beside it without a permission prompt. Remove one and Claudex asks again next time.":
    "Claudex kann jedes Tool auf dem daneben angezeigten SSH-Host ohne Berechtigungsabfrage verwenden. Entfernst du eines, fragt Claudex beim nächsten Mal wieder nach.",
  "Nothing here yet. When you choose “Always allow” for a connector tool in an SSH session, it appears here.":
    "Hier ist noch nichts. Wenn du in einer SSH-Sitzung für ein Konnektor-Tool „Immer erlauben“ wählst, erscheint es hier.",
  "{tool} ({server})": "{tool} ({server})",
