  "Browser default": "Browserstandard",
  "Local sessions stay on this computer. Cloud sessions and synced data are stored by your Claudex service. Each model provider's data policies apply to requests it receives.":
    "Lokale Sitzungen bleiben auf diesem Computer. Cloud-Sitzungen und synchronisierte Daten werden bei Ihrem Claudex-Dienst gespeichert. Für Anfragen an einen Modellanbieter gelten dessen Datenrichtlinien.",
  "Local sessions are stored on this computer. Cloud chats, projects and files are stored by your Claudex service.":
    "Lokale Sitzungen werden auf diesem Computer gespeichert. Cloud-Chats, Projekte und Dateien werden bei Ihrem Claudex-Dienst gespeichert.",
  "When your service supports reporting, Preferences below controls whether diagnostic and reply-feedback reports are sent.":
    "Wenn Ihr Dienst Berichte unterstützt, steuern die Einstellungen unten, ob Diagnoseberichte und Feedback zu Antworten gesendet werden.",
  "You can manage your shared chats and artifacts below when sharing is available.":
    "Wenn die Freigabefunktion verfügbar ist, können Sie Ihre geteilten Chats und Artefakte unten verwalten.",
  "Your messages and attached content are sent to the model provider used for that session. That provider's data policies apply.":
    "Ihre Nachrichten und angehängten Inhalte werden an den Modellanbieter der jeweiligen Sitzung gesendet. Es gelten dessen Datenrichtlinien.",
  "Optional diagnostic reports contain error codes and known error descriptions, not prompts, replies or file paths.":
    "Optionale Diagnoseberichte enthalten Fehlercodes und bekannte Fehlerbeschreibungen, keine Prompts, Antworten oder Dateipfade.",
  "Reply feedback can include your rating, selected categories and comment. A conversation excerpt is included only when your service allows it and you choose to include it.":
    "Feedback zu Antworten kann Ihre Bewertung, ausgewählte Kategorien und Ihren Kommentar enthalten. Ein Gesprächsauszug wird nur beigefügt, wenn Ihr Dienst dies erlaubt und Sie es auswählen.",
  "Claudex does not set your model provider's training or retention policy.":
    "Claudex legt die Trainings- oder Aufbewahrungsrichtlinien Ihres Modellanbieters nicht fest.",
