  "Connection events from the current runtime. Server stderr is not available. Credentials are redacted and older events are discarded when the limit is reached.":
    "Verbindungsereignisse der aktuellen Laufzeit. Die Standardfehlerausgabe des Servers ist nicht verfügbar. Zugangsdaten werden unkenntlich gemacht; bei Erreichen des Limits werden ältere Ereignisse verworfen.",
