  "Imported {count} servers. They are disabled. Review and enable them in Developer → Edit config when you trust their commands.":
    "{count} Server importiert. Sie sind deaktiviert. Prüfe und aktiviere sie unter Entwickler → Konfiguration bearbeiten, wenn du ihren Befehlen vertraust.",
  "Review servers from Claude Desktop, Claude Code user settings and Cursor user settings on this computer. Only supported local stdio configurations are offered. Environment credentials are preserved during import and hidden in this preview.":
    "Prüfe Server aus Claude Desktop, den Claude-Code-Benutzereinstellungen und den Cursor-Benutzereinstellungen auf diesem Computer. Es werden nur unterstützte lokale stdio-Konfigurationen angeboten. Zugangsdaten in Umgebungsvariablen bleiben beim Import erhalten und werden in dieser Vorschau ausgeblendet.",
  "MCP commands can access local files and services with your account’s permissions when enabled. Selected servers will be added disabled. Existing servers and their credentials are preserved.":
    "Aktivierte MCP-Befehle können mit den Berechtigungen deines Kontos auf lokale Dateien und Dienste zugreifen. Ausgewählte Server werden deaktiviert hinzugefügt. Vorhandene Server und ihre Zugangsdaten bleiben erhalten.",
