  "For this reflection to work, you’ll need to enable memory in <a>memory settings</a>.":
    "Damit diese Reflexion funktioniert, musst du das Gedächtnis in den <a>Gedächtnis-Einstellungen</a> aktivieren.",
  "Search by name": "Nach Namen suchen",
  "Build connectors and plugins": "Connectoren und Plugins entwickeln",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "Ein Connector ist ein MCP-Server: Er spricht das Model Context Protocol über Streamable HTTP, meldet Personen per OAuth oder Token an und beschreibt die Eingaben und Wirkungen jedes Tools klar. Ein Plugin bündelt Skills, Connectoren und Anweisungen in einem Paket. Füge deinen Connector unter Anpassen → Connectoren als benutzerdefinierten Connector hinzu und probiere ihn in einem Chat aus, bevor du ihn über „An das Verzeichnis senden“ einreichst.",
